#include <vector>
#include <string>
#include <numeric>

class Solution {
public:
    std::vector<std::string> simplifiedFractions(int n) {
        std::vector<std::string> res;
        for (int d = 2; d <= n; ++d) {
            for (int num = 1; num < d; ++num) {
                if (std::gcd(num, d) == 1) {
                    res.push_back(std::to_string(num) + "/" + std::to_string(d));
                }
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    public List<String> simplifiedFractions(int n) {
        List<String> res = new ArrayList<>();
        for (int d = 2; d <= n; d++) {
            for (int num = 1; num < d; num++) {
                if (gcd(num, d) == 1) {
                    res.add(num + "/" + d);
                }
            }
        }
        return res;
    }
}

var simplifiedFractions = function(n) {
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const res = [];
    for (let d = 2; d <= n; d++) {
        for (let num = 1; num < d; num++) {
            if (gcd(num, d) === 1) {
                res.push(`${num}/${d}`);
            }
        }
    }
    return res;
};
